style.css:
@-moz-document domain("google.com") {
/* ===== базовое центрирование (у тебя уже работает) ===== */
body.hp {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    min-height: 100vh !important;
}

/* ===== СКРЫВАЕМ ВСЕ ВАРИАНТЫ ЛОГОТИПА GOOGLE ===== */
svg[aria-label="Google"],
div[aria-label="Google"],
h1 svg,
img[alt="Google"] {
    display: none !important;
}

/* ===== ДОБАВЛЯЕМ СВОЙ ЛОГОТИП ===== */
#searchform::before {
    content: "";
    display: block;
    width: 240px;
    height: 240px;
    margin: 0 auto 28px auto;

    background-image: url("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTNr0sr2h302F_SC7V5amR75086oOeQaMCiPA&s");
    background-repeat: no-repeat;
    background-size: contain;
    background-position: center;
}

/* ===== центрируем форму ===== */
#searchform {
    margin: 0 auto !important;
}

#searchform > div {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
}
}
